import {shiftSecondsLeft,SHIFT_MINUTES} from './shift-clock.mjs?v=four-days-11';
import {mood} from './style-options.mjs?v=four-days-11';
import {cafeSnapshot,reportInsights} from './day.mjs?v=four-days-11';
import {DAYS,mission,missionProgress,rewardFor,settleDay,categoryResults} from './campaign.mjs?v=four-days-11';
const $=s=>document.querySelector(s),n=v=>Math.round(v??0),pct=v=>v==null?'—':n(v)+'%',money=v=>(v<0?'−':'')+'$'+Math.abs(n(v)),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const bars=types=>categoryResults(types).map(t=>`<div class="satisfaction-row"><span>${t.name}</span><div class="satisfaction-track"><i style="width:${t.satisfaction??0}%;background-size:${t.satisfaction?10000/t.satisfaction:100}% 100%"></i></div><b>${pct(t.satisfaction)}</b></div>`).join('');
export function createDayUI(state,actions){
 const modal=$('#dayModal');let speed=1,paused=false,lastSim=null;
 const api={refresh,requestRun,completed,live,restore,get speed(){return state.phase==='intervene'||paused?0:speed},setSpeed:s=>{speed=s},get paused(){return paused}};
 function changed(){state.opened=!['design','renovate','adjust','intervene','day-running'].includes(state.phase);actions.changed();refresh()}
 function show(html){modal.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0}
 modal.addEventListener('cancel',e=>{e.preventDefault();modal.close()});
 function showMission(){const m=mission(state),icons=['☕','🌿','📚','🔥'];show(`<div class="mission-intro"><div class="mission-ribbon">YOUR CAFÉ · YOUR CALL</div><div class="mission-medallion">${icons[state.dayNumber-1]}</div><span class="eyebrow">DAY ${state.dayNumber} OF ${DAYS.length}</span><h1>${esc(m.name)}</h1>${state.dayNumber===1?'<h2>Welcome, Floor Manager!</h2>':''}<p class="mission-hook">${esc(m.hint)}</p><p>Choose what matters. Watch your customers. Try a different approach.</p><button id="beginPlanning" class="green-btn">Make it yours →</button></div>`);$('#beginPlanning').onclick=()=>{state.welcomeSeen=true;state.missionSeen=state.dayNumber;modal.close();actions.save();actions.prepare?.()}}
 function refresh(){
  const phase=state.phase,running=['day-running','intervene'].includes(phase),planning=['design','renovate','adjust'].includes(phase),m=mission(state);
  document.body.dataset.service=phase==='day-running'?'on':'';$('#slotNumber').textContent='DAY '+state.dayNumber+' / '+DAYS.length+(state.attempt>1?' · TRY '+state.attempt:'');$('#slotName').textContent=m.name;
  $('#pauseSim').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation');$('#quizProgress').textContent=phase==='intervene'?'Service paused. Move unoccupied furniture, then continue.':planning?m.hint:'';
  $('#changeBudget').hidden=true;$('#simControls').hidden=!running;$('#livePanel').hidden=!running||phase==='intervene';$('#resultsButton').hidden=!['day-report','campaign-complete'].includes(phase);$('#open').hidden=!(planning||phase==='intervene');$('#open').disabled=false;$('#open').textContent=phase==='intervene'?'Continue service →':'Open café →';$('#simTime').hidden=!running;$('#streakCorner').hidden=!running;
  $('#interveneSim').hidden=true;$('#interveneSim').textContent=phase==='intervene'?'Continue service':'Pause & adjust';$('#pauseSim').textContent=paused?'Resume':'Pause';$('#pauseSim').disabled=phase==='intervene';
  for(const b of document.querySelectorAll('[data-speed]'))b.setAttribute('aria-pressed',+b.dataset.speed===speed);
  const r=lastSim&&running?lastSim.results():null;
  $('#dailyGoals').innerHTML=missionProgress(state,r).map(g=>`<div class="mission-goal ${g.met?'met':''}"><span>${g.met?'✓':'○'} ${g.label}</span>${r?`<b>${n(g.value)}${g.key==='floorFund'?' dollars':''}</b>`:''}</div>`).join('');
  $('#dayDots').innerHTML=DAYS.map((d,i)=>`<span title="Day ${i+1}: ${d.name}" class="${i+1===state.dayNumber?'current':i+1<state.dayNumber?'done':''}">${i+1<state.dayNumber?'✓':i+1}</span>`).join('');
  $('#layoutPreview').hidden=!planning&&phase!=='intervene';
 }
 function requestRun(){
  if(state.phase==='intervene'){actions.cancel();state.phase='day-running';paused=false;changed();actions.resume?.();return}
  if(!['design','renovate','adjust'].includes(state.phase))return;state.openingRepairBudget=0;
  actions.cancel();state.phase='day-running';state.runSnapshot=cafeSnapshot(state);state.runElapsed=0;state.liveCredited=0;api.lastBreak=null;$('#streakNotice').hidden=true;state.interventions=[];paused=false;lastSim=null;modal.close();changed();actions.begin('day',state.runSnapshot);
 }
 function completed(report){creditSales(report);
  state.reports.first||=report;state.reports.current=report;state.phase='day-report';state.runElapsed=0;state.runSnapshot=null;lastSim=null;changed();renderReport();
 }
 function delta(key,r,old,goodUp=true,unit=''){if(!old)return'';const d=r[key]-old[key];return `<small class="delta ${d===0?'same':(d>0)===goodUp?'better':'worse'}">${d>0?'+':''}${d.toFixed(key==='averageTravel'?1:0)}${unit} vs previous try</small>`}
 function renderReport(){
  const r=state.reports.current;if(!r)return;if(r.inspection){show(`<div class="mission-intro"><div class="mission-medallion">🔑</div><h1>Ready to reopen!</h1><p>Open with the layout you chose.</p><p>Tomorrow your first customers will show you what works.</p><button id="acceptInspection" class="green-btn">Day 2 · Make Them Stay →</button></div>`);$('#acceptInspection').onclick=()=>{settleDay(state);modal.close();actions.renovate();changed();showMission()};return}const old=state.reports.previous,goals=missionProgress(state,r),reward=rewardFor(state,r);
  show(`<div class="report-head"><span class="eyebrow">DAY ${state.dayNumber} · ${esc(mission(state).name)} · TRY ${state.attempt}</span><h1>${goals.every(g=>g.met)?'A good day at the café!':'What did your café teach you?'}</h1><div class="score-stamp"><strong>${n(r.score)}</strong><span>/ 100<br>Floor Manager score</span></div></div>
  <div class="report-scroll"><div class="mission-results">${goals.map(g=>`<span class="${g.met?'met':''}">${g.met?'★':'○'} ${g.label} <b>${n(g.value)} / ${g.target}</b></span>`).join('')}</div>
  <div class="metric-grid">${[['Revenue','revenue',money,true],['Customers served','served',n,true],['Left without buying','lost',n,false],['Satisfaction','satisfaction',pct,true],['Average travel','averageTravel',v=>v.toFixed(1)+' min',false],['Seating use','utilization',pct,true]].map(([label,key,format,up])=>`<div class="metric"><small>${label}</small><b>${format(r[key])}</b>${delta(key,r,old,up)}</div>`).join('')}</div>
  <div class="report-columns"><section><h2>Who felt at home?</h2>${bars(r.types)}<p class="metric-note">${n(r.flow)}% flow · ${r.averageStay.toFixed(1)} min average visit · ${n(r.stayRate)}% found a place to stay</p><details><summary>All customer types</summary>${Object.values(r.types).filter(t=>t.count).map(t=>`<p>${esc(t.name)} · ${pct(t.satisfaction)} (${t.count} visitors)</p>`).join('')}</details></section><section><h2>What happened</h2><ul class="insights">${reportInsights(r).slice(0,3).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="metric-note">${r.blockedMinutes.toFixed(1)} customer-minutes blocked · ${r.averageDistance.toFixed(1)} m average travel · ${r.capacity} seats</p></section></div>
  ${old?`<div class="comparison-note">Same customers, same arrival times. ${r.flow>old.flow+1?'Movement improved after your changes.':r.flow<old.flow-1?'Customers experienced more movement delays this time.':'Movement stayed similar.'} ${r.served>old.served?`${r.served-old.served} more customers purchased.`:r.served<old.served?`${old.served-r.served} fewer customers purchased.`:''}</div>`:''}
  <div class="earnings-banner"><span>Unhappy departures: ${r.unhappyDepartures||0} · Best streak: ${r.bestStreak||0} · Tips: ${money(r.tips||0)} · Reputation: ${n(r.reputation??70)}%<br>Upgrade credit earned: ${money(r.upgradeRewards||0)}<br>Shift total</span><strong>${money(r.profit+reward)}</strong><p>${money(r.revenue)} sales − ${money(r.ingredientCosts)} supplies − $30 running costs + ${money(reward)} mission reward</p><small>Sales already reached your bank. Supplies are deducted as drinks sell; running costs and mission rewards settle now. Retrying returns this attempt’s sales income.</small></div>
  ${state.dayNumber===2&&!state.floor?`<p class="milestone">${state.money+r.profit+reward>=250?'Your café can now afford the $250 floorboard upgrade. Bank today’s earnings, then click the floor.':'The floorboards cost $250. Keep serving customers or retry the layout to grow your fund.'}</p>`:''}
  <details class="score-method"><summary>How the score works</summary><p>Satisfaction 36% · flow 18% · seat use 16% · stay rate 14% · balance between customer types 10% · service efficiency 6%. Longer visits can help comfort while reducing turnover.</p></details></div>
  <div class="report-actions"><button id="inspectAfter" class="paper-btn">View café</button><button id="retryDay" class="paper-btn">Improve & retry</button><button id="acceptDay" class="green-btn">${state.dayNumber===DAYS.length?'Bank & finish':'Bank & plan day '+(state.dayNumber+1)} →</button></div>`);
  $('#inspectAfter').onclick=()=>modal.close();$('#retryDay').disabled=state.money<(state.liveCredited||0);$('#retryDay').title=state.money<(state.liveCredited||0)?'Sales were spent on improvements. Bank this day to continue.':'';$('#retryDay').onclick=()=>{if(state.money<(state.liveCredited||0))return;state.money-=state.liveCredited||0;state.liveCredited=0;state.reports.previous=r;state.attempt++;state.phase='adjust';modal.close();lastSim=null;actions.adjust();changed();actions.toast('Same customers. Try a different layout.');};
  $('#acceptDay').onclick=()=>{const amount=settleDay(state);if(amount===false)return;modal.close();actions.renovate();changed();actions.toast(money(amount)+' banked');$('#bankTakings').textContent='$0';$('#bankNote').textContent='Spendable funds shown above';if(state.phase==='campaign-complete')renderFinal();else showMission()};
 }
 function renderFinal(){const h=state.campaignHistory,total=h.reduce((n,d)=>n+d.report.revenue+(d.priorRevenue||0),0),profit=h.reduce((n,d)=>n+d.earned,0),last=h.at(-1)?.report;
  show(`<div class="report-head"><span class="eyebrow">YOUR FOUR-DAY FLOOR MANAGER REPORT</span><h1>A café that grew with you.</h1></div><div class="report-scroll"><div class="metric-grid"><div class="metric"><small>Total sales</small><b>${money(total)}</b></div><div class="metric"><small>Profit + mission rewards</small><b>${money(profit)}</b></div><div class="metric"><small>Final café score</small><b>${n(last?.score)} / 100</b></div></div><div class="week-results">${h.map(d=>`<div><span>Day ${d.day} · ${d.mission}</span><b>${n(d.report.score)} points</b><span>${money(d.report.revenue)} sales</span><span>${d.goals.filter(g=>g.met).length} / ${d.goals.length} goals</span></div>`).join('')}</div>${last?`<h2>Your final café</h2>${bars(last.types)}<p>${pct(last.satisfaction)} satisfaction · ${last.averageStay.toFixed(1)} min average stay · ${pct(last.stayRate)} stayed · ${pct(last.utilization)} seat use · ${pct(last.flow)} flow</p><ul class="insights">${reportInsights(last).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}<div class="learning"><h2>You explored the café as a system.</h2><p>You explored space, customer flow, comfort, capacity and limited resources. Different customers needed different things. A strong layout balances those needs.</p><p>Daily customer mixes differ; daily scores are not a controlled layout comparison. Use “Improve & retry” within a day to test a change fairly.</p></div></div><div class="report-actions"><button class="green-btn" id="finishWeek">View my café</button></div>`);$('#finishWeek').onclick=()=>modal.close();}
 function creditSales(report){const net=report.revenue-report.ingredientCosts,delta=net-(state.liveCredited||0);if(delta){state.money+=delta;state.liveCredited=net;$('#money').textContent=money(state.money);actions.market?.();actions.save()}}
 function live(sim){lastSim=sim;creditSales({revenue:sim.revenue,ingredientCosts:sim.costs});const progress=Math.min(1,sim.time/120),hour=8+Math.floor(progress*10);$('#simTime').textContent=(hour>12?hour-12:hour)+':00 '+(hour>=12?'PM':'AM');
  const seated=sim.parties.filter(g=>g.phase==='seated').reduce((n,g)=>n+g.size,0),waiting=sim.parties.filter(g=>['queued','toOrder','ordering','toPickup','pickupWait'].includes(g.phase)).reduce((n,g)=>n+g.size,0),served=sim.parties.filter(g=>g.served).reduce((n,g)=>n+g.size,0),lost=sim.parties.filter(g=>g.phase==='departed'&&!g.served).reduce((n,g)=>n+g.size,0);
  $('#bankTakings').textContent=money(sim.revenue);$('#bankNote').textContent='Net '+money(sim.revenue-sim.costs-30)+' · banked after the shift';$('#liveSeats').textContent=seated+' / '+sim.seats.length;$('#liveWaiting').textContent=waiting;$('#liveServed').textContent=served;$('#liveRevenue').textContent=money(sim.revenue);$('#liveLost').textContent=lost;$('#liveProfit').textContent=money(sim.revenue-sim.costs-30);$('#liveProgress').max=SHIFT_MINUTES;$('#liveProgress').value=sim.time;const types=categoryResults(sim.liveTypes()),seen=Object.values(sim.liveTypes()).filter(t=>t.count),happy=seen.length?seen.reduce((n,t)=>n+t.satisfaction*t.count,0)/seen.reduce((n,t)=>n+t.count,0):null;$('#overallFace').textContent=mood(happy);$('#overallFace').setAttribute('aria-label',happy==null?'No guests yet':'Happiness '+pct(happy));$('#overallHappy').textContent=pct(happy);$('#moodFill').style.width=(happy||0)+'%';$('#seatFill').max=Math.max(1,sim.seats.length);$('#seatFill').value=seated;$('#queueDots').textContent='●'.repeat(Math.min(waiting,8))+(waiting>8?' +':'');$('#typeSatisfaction').innerHTML=types.map(t=>`<div class="guest-mood" title="${t.name}: ${pct(t.satisfaction)}"><span>${({study:'📚',social:'👥',remote:'💻'})[t.key]}</span><small>${t.key==='study'?'Study':t.key==='social'?'Social':'Work'}</small><progress style="accent-color:${t.satisfaction<35?'#d76c56':t.satisfaction<60?'#d9a940':'#69a666'}" max="100" value="${t.satisfaction||0}" aria-label="${t.name} satisfaction ${pct(t.satisfaction)}"></progress><b>${mood(t.satisfaction)}</b></div>`).join('');
  const alerts=[];$('#operationalAlerts').innerHTML=alerts.map((a,i)=>`<button data-alert="${i}" title="${esc(a.text)}" aria-label="${esc(a.text)}"><span>${({route:'🚧',wait:'⏳',noise:'🔊',groups:'🪑',sales:'🚪',bathroom:'🚻',outlets:'🔌'})[a.key]||'⚠️'}</span>${({route:'Blocked',wait:'Long wait',noise:'Too loud',groups:'No group seats',sales:'Lost sales',bathroom:'Need bathroom',outlets:'Need power'})[a.key]||'Check café'}${a.point?' ↗':''}</button>`).join('');for(const b of document.querySelectorAll('[data-alert]'))b.onclick=()=>actions.focusAlert?.(alerts[+b.dataset.alert]);$('#liveEvent').textContent=sim.rewardMessage||'Help guests before their patience runs out.';$('#liveEvent').hidden=false;$('#streakValue').textContent=sim.streak;$('#cornerStreakValue').textContent=sim.streak;const left=shiftSecondsLeft(sim.time);$('#shiftCountdown').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(sim.streakBreak&&sim.streakBreak.id!==api.lastBreak){api.lastBreak=sim.streakBreak.id;const notice=$('#streakNotice');notice.textContent='Streak of '+sim.streakBreak.count+' lost — help the next guest!';notice.hidden=false;clearTimeout(api.noticeTimer);api.noticeTimer=setTimeout(()=>notice.hidden=true,3500);}$('#tipValue').textContent=money(sim.tips);$('#repValue').textContent=Math.round(sim.reputation)+'%';$('#creditValue').textContent=money(sim.upgradeRewards);$('#comboValue').textContent=Math.min(3,1+Math.floor(sim.streak/3)*.5)+'×';
  const report=sim.results();$('#liveStay').textContent=Math.round(report.averageStay)+'m';$('#liveFlow').textContent=report.flow<40?'🔴':report.flow<70?'🟡':'🟢';$('#dailyGoals').innerHTML=missionProgress(state,report).map(g=>`<div class="mission-goal ${g.met?'met':''}"><span>${g.met?'✓':'○'} ${g.label}</span><b>${n(g.value)}</b></div>`).join('');
 }
 function restore(){refresh();if(state.phase==='day-report')renderReport();if(state.phase==='campaign-complete')renderFinal();if(['design','renovate','adjust'].includes(state.phase)&&state.missionSeen!==state.dayNumber)showMission()}
 $('#resultsButton').onclick=()=>state.phase==='campaign-complete'?renderFinal():renderReport();$('#pauseSim').onclick=()=>{paused=!paused;refresh()};$('#interveneSim').onclick=()=>{if(state.phase==='intervene'){requestRun();return}actions.cancel();if(lastSim)state.runElapsed=lastSim.time;state.phase='intervene';changed();actions.intervene();actions.toast('Service paused. Clear a route or improve an empty seat.');};for(const b of document.querySelectorAll('[data-speed]'))b.onclick=()=>{speed=+b.dataset.speed;refresh()};return api;
}
